import pandas as pd
import numpy as np

dfs = {}
for i in [1, 2, 3, 5]:
    try:
        dfs[i] = pd.read_csv(f"experiment_{i}_csv")
    except Exception as e:
        print(f"Error loading exp {i}: {e}")

for i, df in dfs.items():
    print(f"\n=== Experiment {i} ===")
    print("Columns:", list(df.columns))
    print(df.describe().round(3))
    if "AntimicrobialHopExtract" in df.columns:
        print("Intervention levels:", df["AntimicrobialHopExtract"].unique())
    else:
        print("No intervention column found (likely baseline)")
